def maximum_pair_xor(nums):
    answer = 0
    for bit in range(30,-1,-1):
        prefixes = {value>>bit for value in nums}
        candidate = (answer<<1)|1
        answer <<= 1
        if any((prefix^candidate) in prefixes for prefix in prefixes):
            answer = candidate
    return answer

